-- Load order: _prelude.sql, import.sql, _epilogue.sql
CREATE TABLE external_id_map (                              -- two-way sync (Doc 3 16.2), BRL-025
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  integration_id uuid NOT NULL /* id -> dropped integrations */,
  object_type text NOT NULL, object_id uuid NOT NULL,
  external_system text NOT NULL, external_id text NOT NULL,
  last_synced_at timestamptz, last_external_version text, conflict_policy text NOT NULL DEFAULT 'latest_wins',
  PRIMARY KEY (integration_id, object_type, object_id),
  UNIQUE (integration_id, external_system, external_id)
);

CREATE TABLE import_jobs (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  source text NOT NULL CHECK (source IN ('csv','clickup','asana','jira','monday','trello')),
  file_id uuid /* id -> files.files */,
  mapping jsonb NOT NULL DEFAULT '{}',
  dry_run boolean NOT NULL DEFAULT true,
  stop_on_first_error boolean NOT NULL DEFAULT false,
  status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','running','done','failed','cancelled')),
  rows_total integer, rows_ok integer, rows_failed integer,
  created_by uuid /* id -> identity.users */,
  created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz
);

CREATE TABLE import_row_errors (
  job_id uuid NOT NULL REFERENCES import_jobs(id) ON DELETE CASCADE,
  row_no integer NOT NULL, reason text NOT NULL, raw jsonb,
  PRIMARY KEY (job_id, row_no)
);
